-- 3000 OAuth 2.1 / OpenID Connect provider (owner: authn-oidc-provider;
-- K-80, OIDP-01 … OIDP-12).
--
-- * oidc_clients: the client registry. `client_id` is the public
--   identifier (`oc_` + 128 random bits, generated by the server, never
--   chosen by the admin); confidential clients store only SHA-256 of their
--   256-bit secret (CRY-06 rationale: the preimage has full entropy).
--   Redirect URIs are matched exactly (RFC 8252 loopback ports aside).
-- * oidc_interactions: pending authorization requests (short TTL, single
--   use, bound to the browser by SHA-256 of a cookie value).
-- * oidc_grants: one authorization (user, client, session, scopes); the
--   refresh-token family. Revoking it ends every token issued from it.
--   `session_id` deliberately has no foreign key: the grant is checked
--   against the live session on every use (OIDP-12), and a purged session
--   simply fails that check.
-- * oidc_authorization_codes: single-use codes (SHA-256 stored), one per
--   grant; a replay revokes the grant (RFC 6749 §4.1.2).
-- * oidc_refresh_tokens: rotating refresh tokens (SHA-256 stored); a
--   replayed (already rotated) token revokes the grant.
-- * oidc_access_tokens: `jti` of every issued JWT access token, so that
--   introspection, userinfo and RFC 7009 revocation see revocations.
-- * oidc_consents: what the user approved per client (OIDP-05): scopes and
--   resources (RFC 8707 audiences); a request for anything not covered asks
--   again.
--
-- Every user-bound row cascades with the account (ACC-09). Every foreign
-- key leads an index (K-70, `schema_foreign_keys.rs`); the tables are new,
-- so the indexes are created in the same transaction.

CREATE TABLE oidc_clients (
    id                   uuid        PRIMARY KEY,
    client_id            text        NOT NULL UNIQUE,
    name                 text        NOT NULL,
    client_type          text        NOT NULL,
    application_type     text        NOT NULL,
    secret_hash          bytea,
    secret_rotated_at    timestamptz,
    redirect_uris        text[]      NOT NULL,
    allowed_scopes       text[]      NOT NULL,
    allowed_grant_types  text[]      NOT NULL,
    allowed_resources    text[]      NOT NULL DEFAULT '{}',
    skip_consent         boolean     NOT NULL DEFAULT false,
    disabled             boolean     NOT NULL DEFAULT false,
    created_at           timestamptz NOT NULL,
    updated_at           timestamptz NOT NULL,
    CONSTRAINT oidc_clients_client_id_check
        CHECK (client_id ~ '^oc_[A-Za-z0-9_-]{22}$'),
    CONSTRAINT oidc_clients_name_check CHECK (char_length(name) BETWEEN 1 AND 100),
    CONSTRAINT oidc_clients_type_check CHECK (client_type IN ('confidential', 'public')),
    CONSTRAINT oidc_clients_application_type_check
        CHECK (application_type IN ('web', 'native')),
    CONSTRAINT oidc_clients_secret_check
        CHECK ((client_type = 'confidential') = (secret_hash IS NOT NULL)
               AND (secret_hash IS NULL OR octet_length(secret_hash) = 32)),
    CONSTRAINT oidc_clients_redirect_uris_check
        CHECK (cardinality(redirect_uris) BETWEEN 1 AND 10),
    CONSTRAINT oidc_clients_grant_types_check
        CHECK (cardinality(allowed_grant_types) >= 1
               AND allowed_grant_types <@ ARRAY['authorization_code', 'refresh_token']::text[])
);

CREATE TABLE oidc_interactions (
    id              uuid        PRIMARY KEY,
    client_id       uuid        NOT NULL REFERENCES oidc_clients (id) ON DELETE CASCADE,
    browser_hash    bytea       NOT NULL,
    redirect_uri    text        NOT NULL,
    scopes          text[]      NOT NULL,
    resources       text[]      NOT NULL DEFAULT '{}',
    state           text,
    nonce           text,
    code_challenge  text        NOT NULL,
    prompt_login    boolean     NOT NULL DEFAULT false,
    prompt_consent  boolean     NOT NULL DEFAULT false,
    max_age         bigint,
    acr_values      text[]      NOT NULL DEFAULT '{}',
    created_at      timestamptz NOT NULL,
    expires_at      timestamptz NOT NULL,
    completed_at    timestamptz,
    CONSTRAINT oidc_interactions_browser_hash_check CHECK (octet_length(browser_hash) = 32),
    CONSTRAINT oidc_interactions_code_challenge_check
        CHECK (code_challenge ~ '^[A-Za-z0-9_-]{43}$'),
    CONSTRAINT oidc_interactions_max_age_check CHECK (max_age IS NULL OR max_age >= 0)
);
CREATE INDEX oidc_interactions_client_idx ON oidc_interactions (client_id);
CREATE INDEX oidc_interactions_expires_idx ON oidc_interactions (expires_at);

CREATE TABLE oidc_grants (
    id              uuid        PRIMARY KEY,
    client_id       uuid        NOT NULL REFERENCES oidc_clients (id) ON DELETE CASCADE,
    user_id         uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    session_id      uuid        NOT NULL,
    scopes          text[]      NOT NULL,
    resources       text[]      NOT NULL DEFAULT '{}',
    nonce           text,
    auth_time       timestamptz NOT NULL,
    amr             text[]      NOT NULL DEFAULT '{}',
    acr             text,
    created_at      timestamptz NOT NULL,
    expires_at      timestamptz NOT NULL,
    revoked_at      timestamptz,
    revoked_reason  text,
    CONSTRAINT oidc_grants_revoked_reason_check
        CHECK (revoked_reason IS NULL OR revoked_reason ~ '^[a-z][a-z0-9_]{0,63}$')
);
CREATE INDEX oidc_grants_client_idx ON oidc_grants (client_id);
CREATE INDEX oidc_grants_user_client_idx ON oidc_grants (user_id, client_id);
CREATE INDEX oidc_grants_expires_idx ON oidc_grants (expires_at);

CREATE TABLE oidc_authorization_codes (
    id              uuid        PRIMARY KEY,
    code_hash       bytea       NOT NULL UNIQUE,
    grant_id        uuid        NOT NULL UNIQUE REFERENCES oidc_grants (id) ON DELETE CASCADE,
    redirect_uri    text        NOT NULL,
    code_challenge  text        NOT NULL,
    created_at      timestamptz NOT NULL,
    expires_at      timestamptz NOT NULL,
    consumed_at     timestamptz,
    CONSTRAINT oidc_authorization_codes_hash_check CHECK (octet_length(code_hash) = 32),
    CONSTRAINT oidc_authorization_codes_challenge_check
        CHECK (code_challenge ~ '^[A-Za-z0-9_-]{43}$')
);

CREATE TABLE oidc_refresh_tokens (
    id              uuid        PRIMARY KEY,
    grant_id        uuid        NOT NULL REFERENCES oidc_grants (id) ON DELETE CASCADE,
    token_hash      bytea       NOT NULL UNIQUE,
    created_at      timestamptz NOT NULL,
    expires_at      timestamptz NOT NULL,
    consumed_at     timestamptz,
    CONSTRAINT oidc_refresh_tokens_hash_check CHECK (octet_length(token_hash) = 32)
);
CREATE INDEX oidc_refresh_tokens_grant_idx ON oidc_refresh_tokens (grant_id);

CREATE TABLE oidc_access_tokens (
    jti             uuid        PRIMARY KEY,
    grant_id        uuid        NOT NULL REFERENCES oidc_grants (id) ON DELETE CASCADE,
    expires_at      timestamptz NOT NULL,
    revoked_at      timestamptz
);
CREATE INDEX oidc_access_tokens_grant_idx ON oidc_access_tokens (grant_id);
CREATE INDEX oidc_access_tokens_expires_idx ON oidc_access_tokens (expires_at);

CREATE TABLE oidc_consents (
    user_id         uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    client_id       uuid        NOT NULL REFERENCES oidc_clients (id) ON DELETE CASCADE,
    scopes          text[]      NOT NULL,
    resources       text[]      NOT NULL DEFAULT '{}',
    granted_at      timestamptz NOT NULL,
    updated_at      timestamptz NOT NULL,
    PRIMARY KEY (user_id, client_id)
);
CREATE INDEX oidc_consents_client_idx ON oidc_consents (client_id);
